#pragma once
// 2026-10-20: designed hand grips for parts a hand carries (the manual reload). The tables are generated by
// tools/blender/grip_solve.py, which places the part in the hand and curls each finger joint until its skin
// touches the part (measured on the meshes), and emits:
//   - each finger joint's rotation against its parent (Unreal axes), applied with the clip's own joint
//     offsets so the hand keeps the drawn size;
//   - each part bone's position and rotation against the wrist bone (Unreal axes), where the carry puts it
//     instead of where the clip's hand has it.
namespace bvr::b1r::grips {

struct GripJoint {
    int bone, parent; // engine bone indices of the hands rig
    float q[4];       // rotation against the parent, x y z w
};
struct GripPart {
    const char* bone; // the gun part's bone name
    float p[3];       // against the wrist bone, rig units
    float q[4];       // x y z w
};

} // namespace bvr::b1r::grips
